const BOT_TOKEN = 'REDACTED_TELEGRAM_BOT_TOKEN';
const OPENAI_KEY = 'REDACTED_API_KEY';
const OPENAI_URL = 'https://api.openai.com/v1/chat/completions';

// helper: httpRequest قد يرجع object أو string — نتعامل مع الحالتين
function parseResp(r) {
  if (typeof r === 'string') return JSON.parse(r);
  return r;
}

const msg = .item.json.message;
if (!msg) return [{ json: { action: 'none' } }];

const chatId = String(msg.chat.id);
const text = (msg.text || msg.caption || '').trim();

const staticData = ('global');
if (!staticData.buffers) staticData.buffers = {};
if (!staticData.buffers[chatId]) staticData.buffers[chatId] = { texts: [], photos: [] };
const buffer = staticData.buffers[chatId];

async function tgSend(txt) {
  await this.helpers.httpRequest({
    method: 'POST',
    url: ,
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ chat_id: chatId, text: txt })
  });
}

// استبدال callGemini بـ callOpenAI مع دعم الصور والنص
async function callOpenAI(parts) {
  const content = [];
  for (const part of parts) {
    if (part.text !== undefined) {
      content.push({ type: 'text', text: part.text });
    } else if (part.inline_data) {
      const mime = part.inline_data.mime_type;
      const data = part.inline_data.data;
      if (mime === 'application/pdf') {
        // PDF غير مدعوم في OpenAI Vision — نطلب من المستخدم إرسال صورة
        content.push({ type: 'text', text: '[ملاحظة: PDF غير مدعوم، يرجى إرسال صورة من الجواز أو التذكرة]' });
      } else {
        content.push({
          type: 'image_url',
          image_url: { url:  }
        });
      }
    }
  }

  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: OPENAI_URL,
    headers: {
      'Content-Type': 'application/json',
      'Authorization': 
    },
    body: JSON.stringify({
      model: 'gpt-4o',
      messages: [{ role: 'user', content }],
      response_format: { type: 'json_object' }
    })
  });
  const parsed = parseResp(resp);
  const rawText = parsed?.choices?.[0]?.message?.content || '{}';
  const cleaned = rawText.replace(/\n?/g,'').trim();
  return JSON.parse(cleaned);
}

// ── CLEAR ──
if (text === '✅') {
  staticData.buffers[chatId] = { texts: [], photos: [] };
  await tgSend('🗑️ تم المسح — جاهز لحجز جديد ✅');
  return [{ json: { action: 'none' } }];
}

// ── PROCESS ──
if (text === 'ارسل') {
  if (buffer.texts.length === 0 && buffer.photos.length === 0) {
    await tgSend('⚠️ ما في بيانات. أرسل الصور والنص أولاً ثم اكتب: ارسل');
    return [{ json: { action: 'none' } }];
  }

  await tgSend('⏳ جاري تحليل البيانات...');
  let bookingData = {};
  const errors = [];

  // ── معالجة الصور ──
  for (const fileId of buffer.photos) {
    try {
      const fileInfoResp = await this.helpers.httpRequest({
        method: 'GET',
        url: ,
        headers: { 'Content-Type': 'application/json' }
      });
      const fileInfo = parseResp(fileInfoResp);
      const filePath = fileInfo.result.file_path;

      const fileBytes = await this.helpers.httpRequest({
        method: 'GET',
        url: ,
        encoding: 'arraybuffer'
      });

      const buf = Buffer.from(fileBytes);
      const base64 = buf.toString('base64');
      let mimeType = 'image/jpeg';
      if (buf[0]===0x89 && buf[1]===0x50) mimeType = 'image/png';
      else if (buf[0]===0x25 && buf[1]===0x50) mimeType = 'application/pdf';

      const prompt = ;

      const photoData = await callOpenAI([
        { text: prompt },
        { inline_data: { mime_type: mimeType, data: base64 } }
      ]);

      if (photoData.type === 'passport') {
        bookingData.guest_name = photoData.guest_name;
        bookingData.country = photoData.country;
      } else if (photoData.type === 'ticket') {
        bookingData.check_in = photoData.check_in;
        bookingData.arrival_time = photoData.arrival_time;
        bookingData.check_out = photoData.check_out;
        bookingData.flight_number = photoData.flight_number;
      }
    } catch(e) {
      errors.push('صورة: ' + e.message);
    }
  }

  // ── معالجة النص ──
  if (buffer.texts.length > 0) {
    try {
      const allText = buffer.texts.join('\n');
      const textPrompt = ;

      const textData = await callOpenAI([{ text: textPrompt }]);
      bookingData = { ...bookingData, ...textData };
    } catch(e) {
      errors.push('نص: ' + e.message);
    }
  }

  staticData.buffers[chatId] = { texts: [], photos: [] };

  if (errors.length > 0) {
    await tgSend('⚠️ تنبيه أخطاء:\n' + errors.join('\n'));
  }

  return [{ json: { action: 'process', chatId, bookingData } }];
}

// ── STORE ──
if (msg.photo || msg.document) {
  const fileId = msg.photo ? msg.photo[msg.photo.length-1].file_id : msg.document.file_id;
  buffer.photos.push(fileId);
  if (msg.caption) buffer.texts.push(msg.caption);
  await tgSend();
} else if (text) {
  buffer.texts.push(text);
  await tgSend('📝 تم حفظ النص 👍');
}

return [{ json: { action: 'none' } }];

